          </div>
          <div className="mt-3">
            {getTupleColorStyles ? (
              <WorkflowTupleLegend
                components={messageComponents}
                getColorStyles={getTupleColorStyles}
              />
            ) : (
              <CompactLegend
                components={messageComponents}
                componentColors={effectiveColors}
              />
            )}
          </div>
        </div>
      )}
    </div>
  );
}

