  filename,
  title,
  status,
  currentStep,
  stepTimings,
  aiSummary,
  warnings,
  onEditPrompt,
  onEditComponents,
  onEditSegmentationPrompt,
  onEditSummaryPrompt,
  onEditAnalysisPrompt,
  onEditColoringPrompt,
  onGenerateAnalysis,
  onGenerateSummary,
  dimensions,
