197→/**
198→ * Map a batch of parts to components using AI
199→ */
200→async function mapPartsBatch(
201→  parts: PartWithContext[],
202→  components: string[],
203→  config: ComponentisationConfig,
204→  componentDescriptions?: string,
205→  conversationId?: string,
206→): Promise<Record<string, string>> {
207→  const openai = createOpenAI({
208→    apiKey: config.apiKey,
209→  });
210→
211→  // Create a simplified conversation structure for just these parts
212→  const partsJson = JSON.stringify(parts, null, 2);
213→  const componentsJson = JSON.stringify(components, null, 2);
214→
215→  const prompt = getPrompt("component-mapping", {
216→    conversationJson: partsJson,
217→    componentsJson,
218→    componentDescriptions: componentDescriptions || "",
219→  });
220→
221→  try {
222→    const result = await generateText({
223→      model: openai(config.model),
224→      prompt,
225→    });
226→
227→    // Parse the JSON response
228→    const jsonMatch = result.text.match(/\{[^]*\}/s);
229→    if (!jsonMatch) {
230→      log(conversationId, "No JSON object found in batch response");
231→      return {};
232→    }
233→
234→    const rawMapping = JSON.parse(jsonMatch[0]);
235→
236→    if (typeof rawMapping !== "object" || rawMapping === null) {
237→      log(conversationId, "Parsed batch result is not an object");
238→      return {};
239→    }
240→
241→    // Normalize component names - strip leading "- " that AI might add
242→    const mapping: Record<string, string> = {};
243→    for (const [key, value] of Object.entries(rawMapping)) {
244→      if (typeof value === "string") {
245→        mapping[key] = value.replace(/^-\s*/, "");
246→      }
247→    }
248→
249→    return mapping;
250→  } catch (error) {
251→    logError(conversationId, "Error calling AI for batch mapping", error);
252→    return {};
253→  }
254→}
