387→/**
388→ * Build a timeline of component composition for each message in the conversation
389→ * This allows scrubbing through the conversation to see how components evolve
390→ */
391→export function buildComponentTimeline(
392→  conversation: Conversation,
393→  componentMapping: Record<string, string>,
394→  conversationId?: string,
395→): ComponentTimelineSnapshot[] {
396→  log(conversationId, "Building component timeline");
397→
398→  // Build a map of part ID to its message index and token count
399→  const partInfo = new Map<
400→    string,
401→    { messageIndex: number; tokenCount: number }
402→  >();
403→  conversation.messages.forEach((message, messageIndex) => {
404→    message.parts.forEach((part) => {
405→      const tokenCount = ("token_count" in part && part.token_count) || 0;
406→      partInfo.set(part.id, { messageIndex, tokenCount });
407→    });
408→  });
409→
410→  // Log mapping coverage for debugging
411→  const mappedCount = Object.keys(componentMapping).length;
412→  const totalParts = partInfo.size;
413→  log(
414→    conversationId,
415→    `Mapping coverage: ${mappedCount}/${totalParts} parts (${Math.round((mappedCount / totalParts) * 100)}%)`,
416→  );
417→
418→  // Build timeline snapshots
419→  const timeline: ComponentTimelineSnapshot[] = [];
420→
421→  for (let msgIndex = 0; msgIndex < conversation.messages.length; msgIndex++) {
422→    const componentTokens: Record<string, number> = {};
423→    let totalTokens = 0;
424→
425→    // Accumulate tokens for ALL parts up to and including this message
426→    // Use mapping if available, otherwise assign to "other"
427→    partInfo.forEach((info, partId) => {
428→      if (info.messageIndex <= msgIndex) {
429→        const component = componentMapping[partId] || "other";
430→        componentTokens[component] =
431→          (componentTokens[component] || 0) + info.tokenCount;
432→        totalTokens += info.tokenCount;
433→      }
434→    });
435→
436→    timeline.push({
437→      messageIndex: msgIndex,
438→      componentTokens,
439→      totalTokens,
440→    });
441→  }
442→
443→  log(conversationId, `Built timeline with ${timeline.length} snapshots`);
444→  return timeline;
445→}
