  1→import { useState, useMemo } from "react";
  2→import { Slider } from "@/components/ui/slider";
  3→import { WaffleChart } from "./WaffleChart";
  4→import { CompactLegend } from "./ComponentComparisonView";
  5→import { cn } from "@/lib/utils";
  6→import { getComponentWaffleStyles, blendColors, getComponentWaffleHex } from "@/lib/component-colors";
  7→import { getStaticComponentLabel } from "@/lib/static-component-colors";
  8→import type { Conversation } from "@/schema";
  9→import { computeTupleTokens, TUPLE_SEPARATOR, type ComponentTimelineSnapshot, type DimensionData } from "@/componentisation";
 10→
 11→// Message type filter in format "role:type" (e.g., "assistant:tool-call")
 12→type MessageTypeFilter = string;
 13→
 14→interface ComponentsViewProps {
 15→  componentMapping?: Record<string, string>;
 16→  conversation: Conversation;
 17→  componentTimeline?: ComponentTimelineSnapshot[];
 18→  componentColors?: Record<string, string>;
 19→  // Multi-dimensional component data
 20→  dimensions?: Record<string, DimensionData>;
 21→  activeDimensions?: Set<string>;
 22→  onActiveDimensionsChange?: (dims: Set<string>) => void;
 23→  selectedComponent?: string | null;
 24→  onComponentSelect?: (component: string | null) => void;
 25→  // Static component filter - when set, only show automatic components for parts matching this static component
 26→  staticMapping?: Record<string, string>;
 27→  filterByStaticComponent?: string | null;
 28→  // Filters from conversation view
 29→  messageTypeFilters?: Set<MessageTypeFilter>;
 30→}
 31→
 32→export function ComponentsView({
 33→  componentMapping,
 34→  conversation,
 35→  componentTimeline,
 36→  componentColors,
 37→  dimensions,
 38→  activeDimensions: activeDimensionsProp,
 39→  onActiveDimensionsChange,
 40→  selectedComponent,
 41→  onComponentSelect,
 42→  staticMapping,
 43→  filterByStaticComponent,
 44→  messageTypeFilters,
 45→}: ComponentsViewProps) {
 46→  // Initialize slider to the last message
 47→  const [currentMessageIndex, setCurrentMessageIndex] = useState(
 48→    conversation.messages.length - 1
 49→  );
 50→
 51→  const activeDimensions = activeDimensionsProp || new Set(["default"]);
 52→  // Stable key for memoization (Set identity isn't reliable for useMemo deps)
 53→  const activeDimensionsKey = [...activeDimensions].sort().join(",");
 54→  // Deep-ish key to detect when dimension data actually changes (e.g. new components/colors after processing)
 55→  const dimensionsDataKey = useMemo(() => {
 56→    if (!dimensions) return "";
 57→    return Object.entries(dimensions)
 58→      .map(([name, dim]) => `${name}:${dim.components.length}:${Object.keys(dim.componentMapping).length}`)
 59→      .sort()
 60→      .join("|");
 61→  }, [dimensions]);
 62→  const dimensionNames = useMemo(
 63→    () => dimensions ? Object.keys(dimensions) : [],
 64→    [dimensions],
 65→  );
 66→  const hasMultipleDimensions = dimensionNames.length > 1;
 67→
 68→  // The "primary" dimension is the first active one (used for waffle grid layout)
 69→  const primaryDimName = useMemo(() => {
 70→    const active = [...activeDimensions];
 71→    return active[0] || (dimensionNames[0] ?? "default");
 72→  }, [activeDimensionsKey, dimensionNames]);
 73→
 74→  // Determine effective mapping and colors based on active dimensions
 75→  const effectiveMapping = useMemo(() => {
 76→    if (!dimensions) return componentMapping || {};
 77→    // Always use the primary (first active) dimension's mapping
 78→    return dimensions[primaryDimName]?.componentMapping || componentMapping || {};
 79→  }, [dimensions, dimensionsDataKey, primaryDimName, componentMapping]);
 80→
 81→  const effectiveColors = useMemo(() => {
 82→    if (!dimensions) return componentColors || {};
 83→    return dimensions[primaryDimName]?.componentColors || componentColors || {};
 84→  }, [dimensions, dimensionsDataKey, primaryDimName, componentColors]);
 85→
 86→  // Helper to check if a part passes the message type filter
 87→  const partPassesMessageTypeFilter = (part: { type: string }, msgRole: string): boolean => {
 88→    if (!messageTypeFilters || messageTypeFilters.has("all")) return true;
 89→    const filterKey = `${msgRole}:${part.type}`;
 90→    return messageTypeFilters.has(filterKey);
 91→  };
 92→
 93→  // Get the set of part IDs that match the static component filter
 94→  const filteredPartIds = useMemo(() => {
 95→    if (!filterByStaticComponent || !staticMapping) return null;
 96→
 97→    const ids = new Set<string>();
 98→    for (const [partId, staticComp] of Object.entries(staticMapping)) {
 99→      if (staticComp === filterByStaticComponent) {
100→        ids.add(partId);
101→      }
102→    }
103→    return ids;
104→  }, [filterByStaticComponent, staticMapping]);
105→
106→  // Compute tuple-based token data when multiple dimensions are active
107→  // Each tuple is a unique combination of components across active dimensions (e.g. "error_types:X · workflow:Y")
108→  const tupleData = useMemo(() => {
109→    if (!dimensions || activeDimensions.size <= 1) return null;
110→    return computeTupleTokens(
111→      conversation,
112→      dimensions,
113→      [...activeDimensions].sort(),
114→      {
115→        maxMessageIndex: currentMessageIndex,
116→        filteredPartIds,
117→        partFilter: (part, msgRole) => partPassesMessageTypeFilter(part, msgRole),
118→      },
119→    );
120→  }, [dimensions, dimensionsDataKey, activeDimensionsKey, conversation.messages, currentMessageIndex, filteredPartIds, messageTypeFilters]);
121→
122→  // Helper to get blended color for a tuple key like "dim1:comp1 · dim2:comp2"
123→  const getTupleColorStyles = useMemo(() => {
124→    if (!dimensions || !tupleData) return null;
125→    return (tupleKey: string) => {
126→      const parts = tupleKey.split(TUPLE_SEPARATOR);
127→      const colors: string[] = [];
128→      for (const part of parts) {
129→        const sepIdx = part.indexOf(":");
130→        const dimName = part.slice(0, sepIdx);
131→        const comp = part.slice(sepIdx + 1);
132→        const dim = dimensions[dimName];
133→        if (dim) {
134→          const hex = getComponentWaffleHex(comp, dim.componentColors);
135→          if (hex) colors.push(hex);
136→        }
137→      }
138→      if (colors.length === 0) return { classes: "bg-gray-300" as string | null, style: null as React.CSSProperties | null };
139→      const blended = colors.length === 1 ? colors[0]! : blendColors(colors);
140→      return { classes: null as string | null, style: { backgroundColor: blended } as React.CSSProperties | null };
141→    };
142→  }, [dimensions, dimensionsDataKey, tupleData]);
143→
144→  // Compute messageComponents for workflow view (filtered, up to current slider position)
145→  // When multiple dimensions are active, produces tuple keys matching the waffle chart
146→  const messageComponents = useMemo(() => {
147→    if (!effectiveMapping || Object.keys(effectiveMapping).length === 0) return [];
148→    const isMultiDim = dimensions && activeDimensions.size > 1;
149→    const activeDimNames = isMultiDim ? [...activeDimensions].sort() : null;
150→    const components: string[] = [];
151→    conversation.messages.forEach((message, msgIndex) => {
152→      if (msgIndex <= currentMessageIndex) {
153→        let messageComponent: string | null = null;
154→        for (const part of message.parts) {
155→          if (!partPassesMessageTypeFilter(part, message.role)) continue;
156→          if (filteredPartIds && !filteredPartIds.has(part.id)) continue;
157→
158→          if (isMultiDim && activeDimNames) {
159→            // Build tuple key from all active dimensions
160→            const tupleParts: string[] = [];
161→            for (const dimName of activeDimNames) {
162→              const comp = dimensions![dimName]?.componentMapping[part.id];
163→              if (comp) tupleParts.push(`${dimName}:${comp}`);
164→            }
165→            if (tupleParts.length > 0) {
166→              messageComponent = tupleParts.join(TUPLE_SEPARATOR);
167→              break;
168→            }
169→          } else {
170→            const component = effectiveMapping[part.id];
171→            if (component) {
172→              messageComponent = component;
173→              break;
174→            }
175→          }
176→        }
177→        if (messageComponent !== null) {
178→          components.push(messageComponent);
179→        }
180→      }
181→    });
182→    return components;
183→  }, [conversation.messages, currentMessageIndex, effectiveMapping, dimensions, dimensionsDataKey, activeDimensionsKey, filteredPartIds, messageTypeFilters]);
184→
185→  if (!effectiveMapping || Object.keys(effectiveMapping).length === 0) {
186→    return (
187→      <div className="p-8 text-center text-muted-foreground">
188→        <p>No component mapping available yet.</p>
189→        <p className="text-sm mt-2">
190→          Component mapping will appear here after processing.
191→        </p>
192→      </div>
193→    );
194→  }
195→
196→  // Get component data for the current message, filtered by static component and message type
197→  let componentTokensForOverview: Record<string, number> = {};
198→  let filteredTokensTotal = 0;
199→  let fullTokensTotal = 0;
200→
201→  // Always calculate from conversation to apply filtering
202→  conversation.messages.forEach((message, msgIndex) => {
203→    if (msgIndex <= currentMessageIndex) {
204→      message.parts.forEach((part) => {
205→        const component = effectiveMapping[part.id];
206→        if (component) {
207→          const tokenCount = ("token_count" in part && part.token_count) || 0;
208→          fullTokensTotal += tokenCount;
209→
210→          // Apply message type filter first
211→          if (!partPassesMessageTypeFilter(part, message.role)) return;
212→
213→          // Apply static component filter if set
214→          if (!filteredPartIds || filteredPartIds.has(part.id)) {
215→            componentTokensForOverview[component] =
216→              (componentTokensForOverview[component] || 0) + tokenCount;
217→            filteredTokensTotal += tokenCount;
218→          }
219→        }
220→      });
221→    }
222→  });
223→
224→  const handleComponentClick = (component: string) => {
225→    const newSelection = selectedComponent === component ? null : component;
226→    onComponentSelect?.(newSelection);
227→  };
228→
229→  // Check if message type filters are active
230→  const hasMessageTypeFilters = messageTypeFilters && !messageTypeFilters.has("all") && messageTypeFilters.size > 0;
231→
232→  // Helper to get blended waffle styles for multi-dimension view
233→  const getWaffleStylesForDimensions = (component: string) => {
234→    if (!dimensions || activeDimensions.size <= 1) {
235→      return getComponentWaffleStyles(component, effectiveColors);
236→    }
237→    // Multi-dimension: blend colors
238→    const activeDimNames = [...activeDimensions];
239→    const colors = activeDimNames
240→      .map((dimName) => {
241→        const dim = dimensions[dimName];
242→        if (!dim) return null;
243→        // Find the component color in this dimension
244→        return getComponentWaffleHex(component, dim.componentColors);
245→      })
246→      .filter((c): c is string => c !== null);
247→
248→    if (colors.length === 0) return getComponentWaffleStyles(component, effectiveColors);
249→    const blended = colors.length === 1 ? colors[0]! : blendColors(colors);
250→    return { classes: null, style: { backgroundColor: blended } };
251→  };
252→
253→  const handleToggleDimension = (dimName: string) => {
254→    const next = new Set(activeDimensions);
255→    if (next.has(dimName)) {
256→      if (next.size > 1) next.delete(dimName); // Keep at least one active
257→    } else {
258→      next.add(dimName);
259→    }
260→    onActiveDimensionsChange?.(next);
261→  };
262→
263→  return (
264→    <div className="p-4">
265→      {/* Dimension selector checkboxes */}
266→      {hasMultipleDimensions && (
267→        <div className="mb-3 flex items-center gap-3 text-xs">
268→          <span className="text-muted-foreground font-medium">Dimensions:</span>
269→          {dimensionNames.map((dimName) => (
270→            <label key={dimName} className="flex items-center gap-1 cursor-pointer">
271→              <input
272→                type="checkbox"
273→                checked={activeDimensions.has(dimName)}
274→                onChange={() => handleToggleDimension(dimName)}
275→                className="h-3 w-3 accent-blue-600"
276→              />
277→              <span>{dimName}</span>
278→            </label>
279→          ))}
280→        </div>
281→      )}
282→
283→      {/* Filter indicator */}
284→      {(filterByStaticComponent || hasMessageTypeFilters) && (
285→        <div className="mb-3 text-sm text-blue-600 bg-blue-50 px-3 py-1.5 rounded-md">
286→          {hasMessageTypeFilters && "Filtered view"}
287→          {hasMessageTypeFilters && filterByStaticComponent && " · "}
288→          {filterByStaticComponent && (
289→            <>Filtering by <strong>{getStaticComponentLabel(filterByStaticComponent)}</strong></>
290→          )}
291→          {" · "}{filteredTokensTotal.toLocaleString()} tokens
292→        </div>
293→      )}
294→
295→
296→      {/* Timeline Slider */}
297→      <div className="mb-4 px-2">
298→        <div className="flex items-center justify-between mb-2">
299→          <span className="text-sm font-medium text-muted-foreground">
300→            Message {currentMessageIndex + 1} of {conversation.messages.length}
301→          </span>
302→          <span className="text-sm font-semibold text-foreground">
303→            {fullTokensTotal.toLocaleString()} tokens
304→          </span>
305→        </div>
306→        <Slider
307→          value={[currentMessageIndex]}
308→          onValueChange={(value) => setCurrentMessageIndex(value[0] ?? 0)}
309→          min={0}
310→          max={conversation.messages.length - 1}
311→          step={1}
312→          className="w-full"
313→        />
314→      </div>
315→
316→      {/* Waffle Chart - tuple-based when multi-dimension, single when one dimension */}
317→      {tupleData && getTupleColorStyles ? (
318→        <WaffleChart
319→          componentTokens={tupleData.tupleTokens}
320→          totalTokens={tupleData.total}
321→          getColorStyles={getTupleColorStyles}
322→          getLabel={(tupleKey) => tupleKey}
323→          onComponentClick={handleComponentClick}
324→        />
325→      ) : (
326→        <WaffleChart
327→          componentTokens={componentTokensForOverview}
328→          totalTokens={filteredTokensTotal}
329→          getColorStyles={(component) => getWaffleStylesForDimensions(component)}
330→          getLabel={(component) => component}
331→          onComponentClick={handleComponentClick}
332→        />
333→      )}
334→
335→      {/* Workflow Diagram - horizontal sequence of messages */}
336→      {messageComponents.length > 0 && (
337→        <div className="mt-6 pt-4 border-t">
338→          <h4 className="text-sm font-medium text-muted-foreground mb-3">
339→            Workflow ({messageComponents.length} messages)
340→          </h4>
341→          <div className="flex flex-wrap gap-0.5">
342→            {messageComponents.map((component, index) => {
343→              const colorStyles = component
344→                ? (getTupleColorStyles ? getTupleColorStyles(component) : getWaffleStylesForDimensions(component))
345→                : null;
346→              const label = component;
347→              return (
348→                <div
349→                  key={index}
350→                  className={cn(
351→                    "w-3 h-3 flex-shrink-0",
352→                    component ? colorStyles?.classes : "bg-gray-200",
353→                  )}
354→                  style={colorStyles?.style || undefined}
355→                  title={`${index + 1}: ${label || "unknown"}`}
356→                />
357→              );
358→            })}
359→          </div>
360→          <div className="mt-3">
361→            {getTupleColorStyles ? (
362→              <WorkflowTupleLegend
363→                components={messageComponents}
364→                getColorStyles={getTupleColorStyles}
365→              />
366→            ) : (
367→              <CompactLegend
368→                components={messageComponents}
369→                componentColors={effectiveColors}
370→              />
371→            )}
372→          </div>
373→        </div>
374→      )}
375→    </div>
376→  );
377→}
378→
379→// Compact legend for tuple-based workflow view
380→function WorkflowTupleLegend({
381→  components,
382→  getColorStyles,
383→}: {
384→  components: string[];
385→  getColorStyles: (key: string) => { classes: string | null; style: React.CSSProperties | null };
386→}) {
387→  const unique = [...new Set(components)].filter(Boolean);
388→  return (
389→    <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs">
390→      {unique.map((tupleKey) => {
391→        const colorStyles = getColorStyles(tupleKey);
392→        const label = tupleKey;
393→        return (
394→          <div key={tupleKey} className="flex items-center gap-1.5">
395→            <span
396→              className={cn("w-3 h-3 flex-shrink-0", colorStyles.classes)}
397→              style={colorStyles.style || undefined}
398→            />
399→            <span className="text-muted-foreground [font-variant:small-caps]">{label}</span>
400→          </div>
401→        );
402→      })}
403→    </div>
404→  );
405→}
