 92→export interface ConversationStats {
 93→  messageCount: number;
 94→  turnCount: number;
 95→  durationMs?: number;
 96→}
 97→
 98→/**
 99→ * Generate a streaming AI summary of the conversation
100→ * Calls onChunk with each text chunk as it arrives
101→ * Returns a promise that resolves with the complete summary text and error info
102→ */
103→export async function generateConversationSummary(
104→  conversation: Conversation,
105→  onChunk?: (chunk: string) => void,
106→  customPrompt?: string,
107→  metadata?: ConversationMetadata,
108→  stats?: ConversationStats,
109→  conversationId?: string,
110→): Promise<{ summary: string; error?: string }> {
111→  logSummary(conversationId, "Starting summary generation");
112→
113→  const config = getAIConfig("AI Summary");
114→
115→  if (!config) {
116→    return { summary: "", error: "AI Summary: No API key configured" };
117→  }
118→
119→  const openai = createOpenAI({
120→    apiKey: config.apiKey,
121→  });
122→
123→  // Strip large content (images, files, truncate tool calls/results) - same as componentisation
124→  const strippedConversation = stripLargeContent(conversation);
125→
126→  const prompt = getPrompt("conversation-summary", {
127→    conversationOverview: strippedConversation,
128→    customPrompt,
129→    metadata,
130→    stats,
131→  });
132→
133→  try {
134→    const result = streamText({
135→      model: openai(config.model),
136→      prompt,
137→    });
138→
139→    let fullText = "";
140→
141→    // Stream the chunks
142→    for await (const chunk of result.textStream) {
143→      fullText += chunk;
144→      onChunk?.(chunk);
145→    }
146→
147→    logSummary(conversationId, `Generated summary (${fullText.length} chars)`);
148→    return { summary: fullText };
149→  } catch (error) {
150→    logSummaryError(conversationId, "Error generating summary", error);
151→    const errorMessage =
152→      error instanceof Error ? error.message : "Unknown error";
153→    return { summary: "", error: `AI Summary: ${errorMessage}` };
154→  }
155→}
