157→/**
158→ * Generate CSV data from component timeline for analysis
159→ */
160→function generateComponentCSV(
161→  componentTimeline: ComponentTimelineSnapshot[],
162→  components: string[],
163→  conversation: Conversation,
164→): string {
165→  // CSV header
166→  const header = ["Message", "Total Tokens", ...components].join(",");
167→
168→  // CSV rows
169→  const rows = componentTimeline.map((snapshot, idx) => {
170→    const row = [
171→      `Msg ${idx + 1}`,
172→      snapshot.totalTokens.toString(),
173→      ...components.map((component) => {
174→        const tokens = snapshot.componentTokens[component] || 0;
175→        const percentage =
176→          snapshot.totalTokens > 0
177→            ? ((tokens / snapshot.totalTokens) * 100).toFixed(1)
178→            : "0.0";
179→        return `${tokens} (${percentage}%)`;
180→      }),
181→    ];
182→    return row.join(",");
183→  });
184→
185→  return [header, ...rows].join("\n");
186→}
