188→/**
189→ * Generate AI analysis of context usage patterns
190→ * Analyzes component distribution and provides recommendations for improvement
191→ */
192→export async function generateContextAnalysis(
193→  conversation: Conversation,
194→  componentTimeline: ComponentTimelineSnapshot[],
195→  components: string[],
196→  aiSummary: string,
197→  onChunk?: (chunk: string) => void,
198→  customPrompt?: string,
199→  conversationId?: string,
200→  dimensions?: Record<string, DimensionData>,
201→): Promise<{ analysis: string; error?: string }> {
202→  logAnalysis(conversationId, "Starting analysis generation");
203→
204→  const config = getAIConfig("Context Analysis");
205→
206→  if (!config) {
207→    return { analysis: "", error: "Context Analysis: No API key configured" };
208→  }
209→
210→  const openai = createOpenAI({
211→    apiKey: config.apiKey,
212→  });
213→
214→  // Generate component data for analysis
215→  let allCSVData: string;
216→  if (dimensions && Object.keys(dimensions).length > 1) {
217→    // Multi-dimension: use shared tuple computation (same data as waffle chart)
218→    const { tupleTokens, total } = computeTupleTokens(conversation, dimensions);
219→    const sorted = Object.entries(tupleTokens).sort((a, b) => b[1] - a[1]);
220→    const dimNames = Object.keys(dimensions).sort();
221→    const lines = sorted.map(([tuple, tokens]) => {
222→      const pct = total > 0 ? ((tokens / total) * 100).toFixed(1) : "0.0";
223→      return `${tuple}: ${tokens} tokens (${pct}%)`;
224→    });
225→    allCSVData = `Dimensions: ${dimNames.join(", ")}\nTotal: ${total} tokens\n\n${lines.join("\n")}`;
226→  } else if (dimensions && Object.keys(dimensions).length === 1) {
227→    // Single dimension: use its timeline
228→    const dim = Object.values(dimensions)[0]!;
229→    allCSVData = generateComponentCSV(
230→      dim.componentTimeline,
231→      [...new Set(dim.components)],
232→      conversation,
233→    );
234→  } else {
235→    // Fallback to legacy single-dimension data
236→    allCSVData = generateComponentCSV(
237→      componentTimeline,
238→      components,
239→      conversation,
240→    );
241→  }
242→
243→  const prompt = getPrompt("context-analysis", {
244→    conversationSummary: aiSummary,
245→    componentDataCSV: allCSVData,
246→    customPrompt,
247→  });
248→
249→  try {
250→    const result = streamText({
251→      model: openai(config.model),
252→      prompt,
253→    });
254→
255→    let fullText = "";
256→
257→    // Stream the chunks
258→    for await (const chunk of result.textStream) {
259→      fullText += chunk;
260→      onChunk?.(chunk);
261→    }
262→
263→    logAnalysis(
264→      conversationId,
265→      `Generated analysis (${fullText.length} chars)`,
266→    );
267→    return { analysis: fullText };
268→  } catch (error) {
269→    logAnalysisError(conversationId, "Error generating analysis", error);
270→    const errorMessage =
271→      error instanceof Error ? error.message : "Unknown error";
272→    return { analysis: "", error: `Context Analysis: ${errorMessage}` };
273→  }
274→}
