 27→/**
 28→ * Format duration in a human-readable format
 29→ */
 30→function formatDuration(ms: number): string {
 31→  const seconds = Math.floor(ms / 1000);
 32→  const minutes = Math.floor(seconds / 60);
 33→  const hours = Math.floor(minutes / 60);
 34→
 35→  if (hours > 0) {
 36→    const remainingMinutes = minutes % 60;
 37→    return `${hours}h ${remainingMinutes}m`;
 38→  } else if (minutes > 0) {
 39→    const remainingSeconds = seconds % 60;
 40→    return `${minutes}m ${remainingSeconds}s`;
 41→  } else {
 42→    return `${seconds}s`;
 43→  }
 44→}
 45→
 46→/**
 47→ * Extract the category (prefix before first dot) from a component name
 48→ */
 49→function getCategory(component: string): string {
 50→  const dotIndex = component.indexOf(".");
 51→  return dotIndex > 0 ? component.substring(0, dotIndex) : component;
 52→}
 53→
 54→/**
 55→ * Sort components by category - groups components by their prefix,
 56→ * sorts categories by total tokens, then sorts within each category by tokens
 57→ */
 58→function sortByCategory(
 59→  componentTokens: Record<string, number>,
 60→  direction: SortDirection
 61→): Array<{ component: string; tokens: number; percentage: number; category: string }> {
 62→  // Calculate total tokens
 63→  const totalTokens = Object.values(componentTokens).reduce((sum, t) => sum + t, 0);
 64→
 65→  // Build component data with category info
 66→  const componentData = Object.entries(componentTokens).map(([component, tokens]) => ({
 67→    component,
 68→    tokens,
 69→    percentage: totalTokens > 0 ? (tokens / totalTokens) * 100 : 0,
 70→    category: getCategory(component),
 71→  }));
 72→
 73→  // Calculate category totals
 74→  const categoryTotals: Record<string, number> = {};
 75→  for (const { category, tokens } of componentData) {
 76→    categoryTotals[category] = (categoryTotals[category] || 0) + tokens;
 77→  }
 78→
 79→  // Sort: first by category total, then by individual tokens within category
 80→  const dir = direction === "asc" ? 1 : -1;
 81→  return componentData.sort((a, b) => {
 82→    const categoryCompare = ((categoryTotals[b.category] || 0) - (categoryTotals[a.category] || 0)) * dir;
 83→    if (categoryCompare !== 0) return categoryCompare;
 84→    // Within same category, sort by tokens in same direction
 85→    return (b.tokens - a.tokens) * dir;
 86→  });
 87→}
