191→/**
192→ * Mini waffle chart for comparison view - smaller 10x10 grid
193→ */
194→function MiniWaffleChart({
195→  componentTokens,
196→  totalTokens,
197→  componentColors,
198→  sortField,
199→  sortDirection,
200→}: {
201→  componentTokens: Record<string, number>;
202→  totalTokens: number;
203→  componentColors?: Record<string, string>;
204→  sortField: SortField;
205→  sortDirection: SortDirection;
206→}) {
207→  const GRID_SIZE = 100; // 10x10 grid for mini version
208→
209→  // Calculate percentages and sort based on field and direction
210→  const componentData = sortField === "category"
211→    ? sortByCategory(componentTokens, sortDirection)
212→    : Object.entries(componentTokens)
213→        .map(([component, tokens]) => ({
214→          component,
215→          tokens,
216→          percentage: totalTokens > 0 ? (tokens / totalTokens) * 100 : 0,
217→        }))
218→        .sort((a, b) => {
219→          const dir = sortDirection === "asc" ? 1 : -1;
220→          if (sortField === "name") {
221→            return a.component.localeCompare(b.component) * dir;
222→          }
223→          return (b.percentage - a.percentage) * dir;
224→        });
225→
226→  // Build the 100-square grid
227→  const squares: { component: string; index: number }[] = [];
228→  let squareIndex = 0;
229→
230→  for (const { component, percentage } of componentData) {
231→    const squareCount = Math.max(
232→      percentage > 0 ? 1 : 0,
233→      Math.round(percentage)
234→    );
235→
236→    for (let i = 0; i < squareCount && squareIndex < GRID_SIZE; i++) {
237→      squares.push({ component, index: squareIndex });
238→      squareIndex++;
239→    }
240→  }
241→
242→  while (squares.length < GRID_SIZE) {
243→    squares.push({ component: "", index: squares.length });
244→  }
245→  squares.length = GRID_SIZE;
246→
247→  return (
248→    <div className="flex-shrink-0 w-[138px] h-[138px]">
249→      <div className="grid grid-cols-[repeat(10,minmax(0,1fr))] gap-0.5">
250→        {squares.map(({ component, index }) => {
251→          const colorStyles = component ? getComponentWaffleStyles(component, componentColors) : null;
252→          return (
253→            <div
254→              key={index}
255→              className={cn(
256→                "w-3 h-3",
257→                component ? colorStyles?.classes : "bg-gray-200"
258→              )}
259→              style={colorStyles?.style || undefined}
260→              title={component || undefined}
261→            />
262→          );
263→        })}
264→      </div>
265→    </div>
266→  );
267→}
