271→ */
272→function formatTokenCount(tokens: number): string {
273→  if (tokens >= 1000) {
274→    const k = tokens / 1000;
275→    return k % 1 === 0 ? `${k}k` : `${k.toFixed(1)}k`;
276→  }
277→  return String(tokens);
278→}
