280→/**
281→ * Absolute waffle chart - each square = tokensPerSquare tokens
282→ * Height varies based on total tokens, enabling cross-conversation comparison
283→ */
284→function AbsoluteWaffleChart({
285→  componentTokens,
286→  totalTokens,
287→  componentColors,
288→  sortField,
289→  sortDirection,
290→  maxRows,
291→  tokensPerSquare,
292→  columns,
293→}: {
294→  componentTokens: Record<string, number>;
295→  totalTokens: number;
296→  componentColors?: Record<string, string>;
297→  sortField: SortField;
298→  sortDirection: SortDirection;
299→  maxRows: number;
300→  tokensPerSquare: number;
301→  columns: number;
302→}) {
303→  // Sort components
304→  const componentData = sortField === "category"
305→    ? sortByCategory(componentTokens, sortDirection)
306→    : Object.entries(componentTokens)
307→        .map(([component, tokens]) => ({
308→          component,
309→          tokens,
310→          percentage: totalTokens > 0 ? (tokens / totalTokens) * 100 : 0,
311→        }))
312→        .sort((a, b) => {
313→          const dir = sortDirection === "asc" ? 1 : -1;
314→          if (sortField === "name") {
315→            return a.component.localeCompare(b.component) * dir;
316→          }
317→          return (b.tokens - a.tokens) * dir;
318→        });
319→
320→  // Build squares array - fill with components
321→  const squares: { component: string }[] = [];
322→  for (const { component, tokens } of componentData) {
323→    const count = Math.max(tokens > 0 ? 1 : 0, Math.round(tokens / tokensPerSquare));
324→    for (let i = 0; i < count; i++) {
325→      squares.push({ component });
326→    }
327→  }
328→
329→  // Clamp and pad to exactly fill the grid (maxRows * columns)
330→  const totalCells = maxRows * columns;
331→  squares.length = Math.min(squares.length, totalCells);
332→  while (squares.length < totalCells) {
333→    squares.push({ component: "" });
334→  }
335→
336→  // Reverse so filled squares are at the bottom (CSS grid fills top-to-bottom)
337→  // We want the chart to grow upward from the baseline
338→  const reversed = [...squares].reverse();
339→
340→  return (
341→    <div className="flex flex-col items-center">
342→      <div className="text-xs text-muted-foreground mb-1 tabular-nums [font-variant:small-caps]">
343→        {formatTokenCount(totalTokens)}
344→      </div>
345→      <div
346→        className="grid gap-0.5"
347→        style={{
348→          gridTemplateColumns: `repeat(${columns}, 12px)`,
349→          gridTemplateRows: `repeat(${maxRows}, 12px)`,
350→        }}
351→      >
352→        {reversed.map((sq, index) => {
353→          const colorStyles = sq.component
354→            ? getComponentWaffleStyles(sq.component, componentColors)
355→            : null;
356→          return (
357→            <div
358→              key={index}
359→              className={cn(
360→                "w-3 h-3",
361→                sq.component ? colorStyles?.classes : "",
362→              )}
363→              style={colorStyles?.style || undefined}
364→              title={sq.component || undefined}
365→            />
366→          );
367→        })}
368→      </div>
369→    </div>
370→  );
371→}
