  2→import type { ConversationMetadata } from "@/parser";
  3→import type { DimensionData } from "@/componentisation";
  4→import {
  5→  SessionExportSchema,
  6→  type SessionExport,
  7→  type FileExport,
  8→  type AnalyticsExport,
  9→  type ExportConversation,
 10→  type ExportDimension,
 11→  type ExportPart,
 12→} from "./export-schema";
 13→
 14→/**
 15→ * Minimal WorkflowState interface for export building.
 16→ * Matches the subset of fields we need from the full WorkflowState in App.tsx.
 17→ */
 18→interface WorkflowState {
 19→  id: string;
 20→  filename: string;
 21→  title?: string; // Custom display title
 22→  status?: "pending" | "processing" | "success" | "failed" | "paused-for-api-key";
 23→  conversation?: Conversation;
 24→  componentMapping?: Record<string, string>;
 25→  componentColors?: Record<string, string>;
 26→  aiSummary?: string;
 27→  analysis?: string;
 28→  metadata?: ConversationMetadata;
 29→  isGrouped?: boolean;
 30→  sourceConversations?: Array<{ id: string; filename: string; title?: string }>;
 31→  dimensions?: Record<string, DimensionData>;
 32→  // Custom prompts
 33→  customPrompt?: string;
 34→  customSegmentationPrompt?: string;
 35→  customSummaryPrompt?: string;
 36→  customAnalysisPrompt?: string;
 37→  customColoringPrompt?: string;
 38→}
 39→
 40→/**
 41→ * Build conversation with component embedded in each part
 42→ */
 43→function buildConversationWithComponents(
 44→  conversation: Conversation,
 45→  componentMapping?: Record<string, string>,
 46→  dimensions?: Record<string, DimensionData>,
 47→): ExportConversation {
 48→  const hasDimensions = dimensions && Object.keys(dimensions).length > 1;
 49→  return {
 50→    messages: conversation.messages.map((message) => ({
 51→      id: message.id,
 52→      role: message.role,
 53→      timestamp: message.timestamp,
 54→      parts: message.parts.map((part) => {
 55→        const exported: ExportPart = {
 56→          ...part,
 57→          component: componentMapping?.[part.id],
 58→        };
 59→        // Embed per-dimension component mappings when multiple dimensions exist
 60→        if (hasDimensions) {
 61→          const dimMap: Record<string, string> = {};
 62→          for (const [dimName, dim] of Object.entries(dimensions!)) {
 63→            const comp = dim.componentMapping[part.id];
 64→            if (comp) dimMap[dimName] = comp;
 65→          }
 66→          if (Object.keys(dimMap).length > 0) {
 67→            exported.dimensions = dimMap;
 68→          }
 69→        }
 70→        return exported;
 71→      }),
 72→    })),
 73→  };
 74→}
 75→
 76→/**
 77→ * Build export data for a single file/conversation
 78→ */
 79→export function buildFileExport(conv: WorkflowState): FileExport {
 80→  if (!conv.conversation) {
 81→    throw new Error(`Cannot export conversation ${conv.id}: no conversation data`);
 82→  }
 83→
 84→  const conversationWithComponents = buildConversationWithComponents(
 85→    conv.conversation,
 86→    conv.componentMapping,
 87→    conv.dimensions,
 88→  );
 89→
 90→  // Build custom prompts object only if any prompts are customized
 91→  const customPrompts = conv.customPrompt || conv.customSegmentationPrompt ||
 92→    conv.customSummaryPrompt || conv.customAnalysisPrompt || conv.customColoringPrompt
 93→    ? {
 94→        componentIdentification: conv.customPrompt,
 95→        segmentation: conv.customSegmentationPrompt,
 96→        summary: conv.customSummaryPrompt,
 97→        analysis: conv.customAnalysisPrompt,
 98→        coloring: conv.customColoringPrompt,
 99→      }
100→    : undefined;
101→
102→  // Build per-dimension export data when multiple dimensions exist
103→  let dimensionsExport: Record<string, ExportDimension> | undefined;
104→  if (conv.dimensions && Object.keys(conv.dimensions).length > 1) {
105→    dimensionsExport = {};
106→    for (const [dimName, dim] of Object.entries(conv.dimensions)) {
107→      dimensionsExport[dimName] = {
108→        components: dim.components,
109→        colors: dim.componentColors,
110→        prompt: dim.prompt,
111→        coloringPrompt: dim.customColoringPrompt,
112→      };
113→    }
114→  }
115→
116→  const result: FileExport = {
117→    id: conv.id,
118→    filename: conv.filename,
119→    conversation: conversationWithComponents,
120→    colors: conv.componentColors || {},
121→    summary: conv.aiSummary || null,
122→    analysis: conv.analysis || null,
123→    metadata: conv.metadata,
124→    customPrompts,
125→  };
126→  if (conv.title) {
127→    result.title = conv.title;
128→  }
129→  if (dimensionsExport) {
130→    result.dimensions = dimensionsExport;
131→  }
132→  return result;
133→}
134→
135→/**
136→ * Build analytics data from conversations
137→ */
138→function buildAnalytics(conversations: WorkflowState[]): AnalyticsExport {
139→  return {
140→    componentComparison: conversations.map((conv) => {
141→      const componentTokens: Record<string, number> = {};
142→      let totalTokens = 0;
143→
144→      conv.conversation?.messages.forEach((msg) => {
145→        msg.parts.forEach((part) => {
146→          const tokens = ("token_count" in part && part.token_count) || 0;
147→          const component = conv.componentMapping?.[part.id] || "other";
148→          componentTokens[component] = (componentTokens[component] || 0) + tokens;
149→          totalTokens += tokens;
150→        });
151→      });
152→
153→      const analytics: AnalyticsExport["componentComparison"][number] = {
154→        fileId: conv.id,
155→        filename: conv.filename,
156→        totalTokens,
157→        turnCount:
158→          conv.conversation?.messages.filter((m) => m.role === "user").length ||
159→          0,
160→        messageCount: conv.conversation?.messages.length || 0,
161→        componentTokens,
162→      };
163→      if (conv.title) {
164→        analytics.title = conv.title;
165→      }
166→      return analytics;
167→    }),
168→  };
169→}
170→
171→/**
172→ * Build complete session export from all conversations
173→ */
174→export function buildSessionExport(
175→  conversations: WorkflowState[],
176→): SessionExport {
177→  // Only include successfully processed individual files (not grouped)
178→  const individualFiles = conversations.filter(
179→    (c) => !c.isGrouped && c.status === "success" && c.conversation,
180→  );
181→
182→  // Get grouped conversations
183→  const groups = conversations.filter((c) => c.isGrouped);
184→
185→  const data = {
186→    version: "1.0" as const,
187→    exportedAt: new Date().toISOString(),
188→    files: individualFiles.map(buildFileExport),
189→    groups: groups.map((g) => {
190→      const group: { id: string; name: string; title?: string; fileIds: string[] } = {
191→        id: g.id,
192→        name: g.filename,
193→        fileIds: g.sourceConversations?.map((s) => s.id) || [],
194→      };
195→      if (g.title) {
196→        group.title = g.title;
197→      }
198→      return group;
199→    }),
200→    analytics: buildAnalytics(individualFiles),
201→  };
202→
203→  // Validate against schema (catches bugs during development)
204→  return SessionExportSchema.parse(data);
205→}
206→
207→/**
208→ * Download export data as a JSON file
209→ */
210→export function downloadExport(data: SessionExport): void {
211→  const json = JSON.stringify(data, null, 2);
212→  const blob = new Blob([json], { type: "application/json" });
213→  const url = URL.createObjectURL(blob);
214→  const a = document.createElement("a");
215→  a.href = url;
216→  a.download = `context-viewer-export-${new Date().toISOString().split("T")[0]}.json`;
217→  a.click();
218→  URL.revokeObjectURL(url);
219→}
