  6→interface ColorStyles {
  7→  classes: string | null;
  8→  style: React.CSSProperties | null;
  9→}
 10→
 11→interface WaffleChartProps {
 12→  componentTokens: Record<string, number>;
 13→  totalTokens: number;
 14→  getColorStyles: (component: string) => ColorStyles;
 15→  getLabel: (component: string) => string;
 16→  onComponentClick?: (component: string) => void;
 17→  hideLegend?: boolean;
 18→}
 19→
 20→/**
 21→ * Waffle chart visualization showing token distribution as a 20x20 grid
 22→ * Each square represents 0.25% of total tokens
 23→ */
 24→export function WaffleChart({
 25→  componentTokens,
 26→  totalTokens,
 27→  getColorStyles,
 28→  getLabel,
 29→  onComponentClick,
 30→  hideLegend,
 31→}: WaffleChartProps) {
 32→  const [sortMode, setSortMode] = useState<SortMode>("tokens");
 33→  const GRID_SIZE = 400; // 20x20 grid
 34→
 35→  // Calculate percentages and sort based on mode
 36→  const componentData = Object.entries(componentTokens)
 37→    .map(([component, tokens]) => ({
 38→      component,
 39→      tokens,
 40→      percentage: totalTokens > 0 ? (tokens / totalTokens) * 100 : 0,
 41→    }))
 42→    .sort((a, b) => {
 43→      if (sortMode === "name") {
 44→        return a.component.localeCompare(b.component);
 45→      }
 46→      return b.percentage - a.percentage;
 47→    });
 48→
 49→  // Build the 400-square grid (20x20)
 50→  // Each square is assigned to a component based on percentage
 51→  const squares: { component: string; index: number }[] = [];
 52→  let squareIndex = 0;
 53→
 54→  for (const { component, percentage } of componentData) {
 55→    // Calculate squares: percentage * 4 (since 400 squares = 100%)
 56→    // Ensure at least 1 square if component has tokens
 57→    const squareCount = Math.max(
 58→      percentage > 0 ? 1 : 0,
 59→      Math.round(percentage * 4)
 60→    );
 61→
 62→    for (let i = 0; i < squareCount && squareIndex < GRID_SIZE; i++) {
 63→      squares.push({ component, index: squareIndex });
 64→      squareIndex++;
 65→    }
 66→  }
 67→
 68→  // Fill remaining squares with empty (shouldn't happen if percentages add to 100)
 69→  while (squares.length < GRID_SIZE) {
 70→    squares.push({ component: "", index: squares.length });
 71→  }
 72→
 73→  // Trim to exactly 400
 74→  squares.length = GRID_SIZE;
 75→
 76→  return (
 77→    <div className="flex gap-8 items-start">
 78→      {/* Legend (left side) */}
 79→      {!hideLegend && (
 80→      <div className="flex flex-col gap-1.5 min-w-[240px]">
 81→        {/* Sort toggle */}
 82→        <div className="flex items-center gap-1 text-xs text-muted-foreground mb-1 px-2">
 83→          <span>Sort:</span>
 84→          <button
 85→            onClick={() => setSortMode("tokens")}
 86→            className={cn(
 87→              "px-1.5 py-0.5 rounded transition-colors",
 88→              sortMode === "tokens"
 89→                ? "bg-gray-200 text-gray-900"
 90→                : "hover:bg-gray-100"
 91→            )}
 92→          >
 93→            tokens
 94→          </button>
 95→          <button
 96→            onClick={() => setSortMode("name")}
 97→            className={cn(
 98→              "px-1.5 py-0.5 rounded transition-colors",
 99→              sortMode === "name"
100→                ? "bg-gray-200 text-gray-900"
101→                : "hover:bg-gray-100"
102→            )}
103→          >
104→            name
105→          </button>
106→        </div>
107→        {componentData.map(({ component, tokens, percentage }) => {
108→          const colorStyles = getColorStyles(component);
109→          return (
110→            <button
111→              key={component}
112→              onClick={() => onComponentClick?.(component)}
113→              className={cn(
114→                "flex items-center gap-2 text-left text-sm py-1 px-2 rounded hover:bg-gray-100 transition-colors",
115→                onComponentClick && "cursor-pointer"
116→              )}
117→            >
118→              <span
119→                className={cn(
120→                  "w-4 h-4 flex-shrink-0",
121→                  colorStyles.classes
122→                )}
123→                style={colorStyles.style || undefined}
124→              />
125→              <span className="flex-1 truncate">{getLabel(component)}</span>
126→              <span className="text-muted-foreground tabular-nums text-xs w-16 text-right">
127→                {tokens.toLocaleString()}
128→              </span>
129→              <span className="text-muted-foreground tabular-nums w-10 text-right">
130→                {percentage.toFixed(0)}%
131→              </span>
132→            </button>
133→          );
134→        })}
135→      </div>
136→      )}
137→
138→      {/* Waffle grid (right side) - fixed 20x20 square */}
139→      <div className="grid grid-cols-[repeat(20,minmax(0,1fr))] gap-0.5 flex-shrink-0">
140→        {squares.map(({ component, index }) => {
141→          const colorStyles = component ? getColorStyles(component) : null;
142→          return (
143→            <button
144→              key={index}
145→              onClick={() => component && onComponentClick?.(component)}
146→              className={cn(
147→                "w-3 h-3 transition-all",
148→                component ? colorStyles?.classes : "bg-gray-200",
149→                component && onComponentClick && "cursor-pointer hover:scale-110"
150→              )}
151→              style={colorStyles?.style || undefined}
152→              title={component ? `${getLabel(component)}` : undefined}
153→            />
154→          );
155→        })}
156→      </div>
157→    </div>
158→  );
159→}
