 24→export function StaticComponentsView({
 25→  conversation,
 26→  staticMapping,
 27→  staticTimeline,
 28→  selectedComponent,
 29→  onComponentSelect,
 30→  messageTypeFilters,
 31→}: StaticComponentsViewProps) {
 32→  // Initialize slider to the last message
 33→  const [currentMessageIndex, setCurrentMessageIndex] = useState(
 34→    conversation.messages.length - 1
 35→  );
 36→
 37→  // Helper to check if a part passes the message type filter
 38→  const partPassesFilter = (part: { type: string }, msgRole: string): boolean => {
 39→    if (!messageTypeFilters || messageTypeFilters.has("all")) return true;
 40→    const filterKey = `${msgRole}:${part.type}`;
 41→    return messageTypeFilters.has(filterKey);
 42→  };
 43→
 44→  if (!staticMapping || Object.keys(staticMapping).length === 0) {
 45→    return (
 46→      <div className="p-8 text-center text-muted-foreground">
 47→        <p>No static component mapping available yet.</p>
 48→        <p className="text-sm mt-2">
 49→          Static components will appear here after processing.
 50→        </p>
 51→      </div>
 52→    );
 53→  }
 54→
 55→  // Get component data for the current message, applying filters
 56→  let componentTokens: Record<string, number> = {};
 57→  let totalTokens = 0;
 58→
 59→  // Always calculate with filters applied (can't use timeline with filters)
 60→  conversation.messages.forEach((message, msgIndex) => {
 61→    if (msgIndex <= currentMessageIndex) {
 62→      message.parts.forEach((part) => {
 63→        // Apply message type filter
 64→        if (!partPassesFilter(part, message.role)) return;
 65→
 66→        const component = staticMapping[part.id];
 67→        if (component) {
 68→          const tokenCount = ("token_count" in part && part.token_count) || 0;
 69→          componentTokens[component] = (componentTokens[component] || 0) + tokenCount;
 70→          totalTokens += tokenCount;
 71→        }
 72→      });
 73→    }
 74→  });
 75→
 76→  const handleComponentClick = (component: string) => {
 77→    const newSelection = selectedComponent === component ? null : component;
 78→    onComponentSelect?.(newSelection);
 79→  };
 80→
 81→  // Check if filters are active
 82→  const hasActiveFilters = messageTypeFilters && !messageTypeFilters.has("all") && messageTypeFilters.size > 0;
 83→
 84→  return (
 85→    <div className="p-4">
 86→      {/* Filter indicator */}
 87→      {hasActiveFilters && (
 88→        <div className="mb-3 text-sm text-blue-600 bg-blue-50 px-3 py-1.5 rounded-md">
 89→          Filtered view · {totalTokens.toLocaleString()} tokens
