105→          onValueChange={(value) => setCurrentMessageIndex(value[0] ?? 0)}
106→          min={0}
107→          max={conversation.messages.length - 1}
108→          step={1}
109→          className="w-full"
110→        />
111→      </div>
112→
113→      {/* Waffle Chart */}
114→      <WaffleChart
