  1→import type { Conversation, Message } from "./schema";
  2→import { encoding_for_model, type Tiktoken } from "tiktoken";
  3→
  4→// Reusable encoder instance - created once, reused for all token counting
  5→let encoderInstance: Tiktoken | null = null;
  6→
  7→function getEncoder(): Tiktoken {
  8→  if (!encoderInstance) {
  9→    encoderInstance = encoding_for_model("gpt-4o");
 10→  }
 11→  return encoderInstance;
 12→}
 13→
 14→/**
 15→ * Count tokens in a text string using GPT-4 encoding
 16→ * @param text The text to count tokens for
 17→ * @returns The number of tokens
 18→ */
 19→function countTokens(text: string): number {
 20→  const enc = getEncoder();
 21→  return enc.encode(text).length;
 22→}
 23→
 24→/**
 25→ * Add token counts to all parts in a conversation
 26→ * This is a post-processing step that should be called after parsing
 27→ * @param conversation The parsed conversation without token counts
 28→ * @returns The same conversation with token counts added to all parts
 29→ */
 30→export async function addTokenCounts(
 31→  conversation: Conversation
 32→): Promise<Conversation> {
 33→  const messages: Message[] = [];
 34→
 35→  // Process messages one at a time, yielding to event loop between each
 36→  for (const msg of conversation.messages) {
 37→    messages.push(addTokenCountsToMessage(msg));
 38→    // Yield to event loop every 10 messages to keep UI responsive
 39→    if (messages.length % 10 === 0) {
 40→      await new Promise((resolve) => setTimeout(resolve, 0));
 41→    }
 42→  }
 43→
 44→  return {
 45→    messages,
 46→  };
 47→}
 48→
 49→function addTokenCountsToMessage(message: Message): Message {
 50→  const contentWithCounts = message.parts.map((part) => {
 51→    switch (part.type) {
 52→      case "text":
 53→        return {
 54→          ...part,
 55→          token_count: countTokens(part.text),
 56→        };
 57→
 58→      case "reasoning":
 59→        return {
 60→          ...part,
 61→          token_count: countTokens(part.text),
 62→        };
 63→
 64→      case "tool-call": {
 65→        // Concatenate tool name and arguments for counting
 66→        const textForCounting = `${part.toolName}${JSON.stringify(part.input)}`;
 67→        return {
 68→          ...part,
 69→          token_count: countTokens(textForCounting),
 70→        };
 71→      }
 72→
 73→      case "tool-result": {
 74→        // Concatenate tool name and output for counting
 75→        const textForCounting = `${part.toolName}${JSON.stringify(part.output)}`;
 76→        return {
 77→          ...part,
 78→          token_count: countTokens(textForCounting),
 79→        };
 80→      }
 81→
 82→      case "image":
 83→      case "file":
 84→        // Skip images and files as requested
 85→        return part;
 86→
 87→      default:
 88→        return part;
 89→    }
 90→  });
 91→
 92→  // Preserve the message type by returning the correct structure
 93→  if (message.role === "system") {
 94→    return {
 95→      ...message,
 96→      parts: contentWithCounts as typeof message.parts,
 97→    };
 98→  } else if (message.role === "user") {
 99→    return {
100→      ...message,
101→      parts: contentWithCounts as typeof message.parts,
102→    };
103→  } else if (message.role === "assistant") {
104→    return {
105→      ...message,
106→      parts: contentWithCounts as typeof message.parts,
107→    };
108→  } else {
109→    // tool message
110→    return {
111→      ...message,
112→      parts: contentWithCounts as typeof message.parts,
113→    };
114→  }
115→}
