  4→/**
  5→ * Static componentisation - deterministic component identification
  6→ * based on role + part type (e.g., "user.text", "assistant.tool-call")
  7→ *
  8→ * This runs without AI and provides instant categorization.
  9→ */
 10→
 11→/**
 12→ * Build list of unique static components from a conversation
 13→ * Component names are in format: role.partType (e.g., "user.image")
 14→ */
 15→export function buildStaticComponents(conversation: Conversation): string[] {
 16→  const componentSet = new Set<string>();
 17→
 18→  for (const message of conversation.messages) {
 19→    for (const part of message.parts) {
 20→      const componentName = `${message.role}.${part.type}`;
 21→      componentSet.add(componentName);
 22→    }
 23→  }
 24→
 25→  // Sort for consistent ordering: by role first, then by type
 26→  const roleOrder = ["system", "user", "assistant", "tool"];
 27→  return Array.from(componentSet).sort((a, b) => {
 28→    const [roleA, typeA = ""] = a.split(".");
 29→    const [roleB, typeB = ""] = b.split(".");
 30→    const roleIndexA = roleOrder.indexOf(roleA ?? "");
 31→    const roleIndexB = roleOrder.indexOf(roleB ?? "");
 32→
 33→    if (roleIndexA !== roleIndexB) {
 34→      return roleIndexA - roleIndexB;
 35→    }
 36→    return typeA.localeCompare(typeB);
 37→  });
 38→}
 39→
 40→/**
 41→ * Build mapping of part IDs to static component names
 42→ */
 43→export function buildStaticComponentMapping(
 44→  conversation: Conversation
 45→): Record<string, string> {
 46→  const mapping: Record<string, string> = {};
 47→
 48→  for (const message of conversation.messages) {
 49→    for (const part of message.parts) {
 50→      const componentName = `${message.role}.${part.type}`;
 51→      mapping[part.id] = componentName;
 52→    }
 53→  }
 54→
 55→  return mapping;
 56→}
 57→
 58→/**
 59→ * Build timeline of component token distribution at each message
 60→ * Reuses the same structure as automatic componentisation for compatibility
 61→ */
 62→export function buildStaticComponentTimeline(
 63→  conversation: Conversation,
 64→  mapping: Record<string, string>
 65→): ComponentTimelineSnapshot[] {
 66→  // Build a map of part ID to its message index and token count
 67→  const partInfo = new Map<string, { messageIndex: number; tokenCount: number }>();
 68→
 69→  conversation.messages.forEach((message, messageIndex) => {
 70→    message.parts.forEach((part) => {
 71→      const tokenCount = ("token_count" in part && part.token_count) || 0;
 72→      partInfo.set(part.id, { messageIndex, tokenCount });
 73→    });
 74→  });
 75→
 76→  // Build timeline snapshots (cumulative tokens up to each message)
 77→  const timeline: ComponentTimelineSnapshot[] = [];
 78→
 79→  for (let msgIndex = 0; msgIndex < conversation.messages.length; msgIndex++) {
 80→    const componentTokens: Record<string, number> = {};
 81→    let totalTokens = 0;
 82→
 83→    // Accumulate tokens for all parts up to and including this message
 84→    Object.entries(mapping).forEach(([partId, component]) => {
 85→      const info = partInfo.get(partId);
 86→      if (info && info.messageIndex <= msgIndex) {
 87→        componentTokens[component] = (componentTokens[component] || 0) + info.tokenCount;
 88→        totalTokens += info.tokenCount;
 89→      }
 90→    });
 91→
 92→    timeline.push({
 93→      messageIndex: msgIndex,
 94→      componentTokens,
 95→      totalTokens,
 96→    });
 97→  }
 98→
 99→  return timeline;
100→}
101→
102→/**
103→ * Convenience function to run all static componentisation steps at once
104→ */
105→export function staticComponentise(conversation: Conversation): {
106→  components: string[];
107→  mapping: Record<string, string>;
108→  timeline: ComponentTimelineSnapshot[];
109→} {
110→  const components = buildStaticComponents(conversation);
111→  const mapping = buildStaticComponentMapping(conversation);
112→  const timeline = buildStaticComponentTimeline(conversation, mapping);
113→
114→  return { components, mapping, timeline };
115→}
