151→/**
152→ * Extract all parts from a conversation with their context
153→ */
154→interface PartWithContext {
155→  partId: string;
156→  messageIndex: number;
157→  role: string;
158→  partType: string;
159→  content: unknown;
160→}
161→
162→function extractPartsWithContext(
163→  conversation: Conversation,
164→): PartWithContext[] {
165→  const parts: PartWithContext[] = [];
166→
167→  conversation.messages.forEach((message, messageIndex) => {
168→    message.parts.forEach((part) => {
169→      let content: unknown;
170→
171→      // Extract relevant content based on part type
172→      if (part.type === "text" || part.type === "reasoning") {
173→        content = part.text;
174→      } else if (part.type === "tool-call") {
175→        content = { toolName: part.toolName, input: part.input };
176→      } else if (part.type === "tool-result") {
177→        content = { toolName: part.toolName, output: part.output };
178→      } else if (part.type === "image") {
179→        content = "[IMAGE]";
180→      } else if (part.type === "file") {
181→        content = "[FILE]";
182→      }
183→
184→      parts.push({
185→        partId: part.id,
186→        messageIndex,
187→        role: message.role,
188→        partType: part.type,
189→        content,
190→      });
191→    });
192→  });
193→
194→  return parts;
195→}
