256→/**
257→ * Map message IDs to components using AI
258→ * Processes parts in batches of 20 in parallel for better coverage
259→ * Returns an object mapping message part IDs to component names
260→ */
261→export async function mapComponentsToIds(
262→  conversation: Conversation,
263→  components: string[],
264→  config: ComponentisationConfig,
265→  componentDescriptions?: string,
266→  conversationId?: string,
267→): Promise<Record<string, string>> {
268→  const BATCH_SIZE = 20;
269→
270→  // Strip binary data and extract parts with context
271→  const strippedConversation = stripLargeContent(conversation);
272→  const allParts = extractPartsWithContext(strippedConversation);
273→
274→  log(
275→    conversationId,
276→    `Mapping ${allParts.length} parts in batches of ${BATCH_SIZE} (model: ${config.model})`,
277→  );
278→
279→  // Split parts into batches
280→  const batches: PartWithContext[][] = [];
281→  for (let i = 0; i < allParts.length; i += BATCH_SIZE) {
282→    batches.push(allParts.slice(i, i + BATCH_SIZE));
283→  }
284→
285→  log(conversationId, `Processing ${batches.length} batches in parallel`);
286→
287→  // Process all batches in parallel
288→  const batchResults = await Promise.all(
289→    batches.map((batch, index) => {
290→      log(
291→        conversationId,
292→        `Starting batch ${index + 1}/${batches.length} (${batch.length} parts)`,
293→      );
294→      return mapPartsBatch(batch, components, config, componentDescriptions, conversationId);
295→    }),
296→  );
297→
298→  // Merge all batch results into a single mapping
299→  const mergedMapping: Record<string, string> = {};
300→  batchResults.forEach((batchMapping, index) => {
301→    const entriesCount = Object.keys(batchMapping).length;
302→    log(conversationId, `Batch ${index + 1} returned ${entriesCount} mappings`);
303→    Object.assign(mergedMapping, batchMapping);
304→  });
305→
306→  log(
307→    conversationId,
308→    `Created merged mapping with ${Object.keys(mergedMapping).length} entries (from ${allParts.length} parts)`,
309→  );
310→  return mergedMapping;
311→}
