314→ * Represents one dimension of componentisation.
315→ * Each dimension has its own prompt, components, mapping, colors, and timeline.
316→ */
317→export interface DimensionData {
318→  name: string;
319→  prompt?: string; // custom identification prompt
320→  components: string[];
321→  componentMapping: Record<string, string>; // partId → componentName
322→  componentTimeline: ComponentTimelineSnapshot[];
