328→/**
329→ * Timeline snapshot representing component composition at a specific message
330→ */
331→export interface ComponentTimelineSnapshot {
332→  messageIndex: number;
333→  componentTokens: Record<string, number>; // component name → total tokens
334→  totalTokens: number; // cumulative tokens up to this message
335→}
336→
337→/** Separator used in tuple keys (e.g. "default:comp1 · relevance:comp2") */
338→export const TUPLE_SEPARATOR = " · ";
339→
340→/**
341→ * Compute tuple-based token aggregation across multiple dimensions.
342→ * Each tuple key is a combination like "default:explore.search-files · relevance:relevant".
343→ * Used by both the waffle chart (ComponentsView) and analysis generation.
344→ *
345→ * @param conversation - The conversation to aggregate over
346→ * @param dimensions - All dimensions to combine
347→ * @param activeDimNames - Which dimensions to include (sorted). If omitted, uses all.
348→ * @param options - Optional filtering (message index limit, part ID filter, message type filter)
349→ */
350→export function computeTupleTokens(
351→  conversation: Conversation,
352→  dimensions: Record<string, DimensionData>,
353→  activeDimNames?: string[],
354→  options?: {
355→    maxMessageIndex?: number;
356→    filteredPartIds?: Set<string> | null;
357→    partFilter?: (part: { type: string }, msgRole: string) => boolean;
358→  },
359→): { tupleTokens: Record<string, number>; total: number } {
360→  const dimNames = activeDimNames || Object.keys(dimensions).sort();
361→  const tupleTokens: Record<string, number> = {};
362→  let total = 0;
363→
364→  for (let msgIdx = 0; msgIdx < conversation.messages.length; msgIdx++) {
365→    if (options?.maxMessageIndex !== undefined && msgIdx > options.maxMessageIndex) break;
366→    const message = conversation.messages[msgIdx]!;
367→    for (const part of message.parts) {
368→      const tokenCount = ("token_count" in part && part.token_count) || 0;
369→      if (options?.partFilter && !options.partFilter(part, message.role)) continue;
370→      if (options?.filteredPartIds && !options.filteredPartIds.has(part.id)) continue;
371→
372→      const segments: string[] = [];
373→      for (const dimName of dimNames) {
374→        const comp = dimensions[dimName]?.componentMapping[part.id];
375→        if (comp) segments.push(`${dimName}:${comp}`);
376→      }
377→      if (segments.length === 0) continue;
378→      const tupleKey = segments.join(TUPLE_SEPARATOR);
379→      tupleTokens[tupleKey] = (tupleTokens[tupleKey] || 0) + tokenCount;
380→      total += tokenCount;
381→    }
382→  }
383→
384→  return { tupleTokens, total };
385→}
