488→    });
489→
490→    console.log(`[Componentisation] AI response for colors: ${result.text}`);
491→
492→    // Parse the JSON response
493→    const jsonMatch = result.text.match(/\{[^]*\}/s);
494→    if (!jsonMatch) {
495→      console.log("[Componentisation] No JSON object found in response");
496→      return {};
497→    }
498→
499→    const rawColorMapping = JSON.parse(jsonMatch[0]);
500→
501→    if (typeof rawColorMapping !== "object" || rawColorMapping === null) {
502→      console.log("[Componentisation] Parsed result is not an object");
503→      return {};
504→    }
505→
506→    // Clean up keys - handle various AI response formats:
507→    // - Remove leading "- " that AI might add
508→    // - Extract component name from "name: description" format (some models include descriptions)
509→    const colorMapping: Record<string, string> = {};
510→    for (const [key, value] of Object.entries(rawColorMapping)) {
511→      let cleanKey = key.replace(/^-\s*/, "");
512→
513→      // If the key contains ": " followed by a description, extract just the component name
514→      // e.g., "identity: Establishes who the AI is..." -> "identity"
515→      // But preserve dots in component names like "personality.guidelines"
516→      const colonDescIndex = cleanKey.indexOf(": ");
517→      if (colonDescIndex > 0) {
518→        cleanKey = cleanKey.substring(0, colonDescIndex);
519→      }
520→
521→      if (typeof value === "string") {
522→        colorMapping[cleanKey] = value;
523→      }
524→    }
525→
526→    console.log(
527→      `[Componentisation] Assigned colors to ${Object.keys(colorMapping).length} components`,
528→    );
529→    return colorMapping;
530→  } catch (error) {
531→    console.error("[Componentisation] Error calling AI for colors:", error);
532→    return {};
533→  }
534→}
