536→/**
537→ * Componentise a conversation: identify components and map them to message IDs
538→ * Returns the list of components, the mapping, timeline data, and error info
539→ */
540→export async function componentiseConversation(
541→  conversation: Conversation,
542→  onProgress?: (step: "identifying" | "mapping") => void,
543→  customPrompt?: string,
544→  customComponents?: string[],
545→  conversationId?: string,
546→): Promise<{
547→  components: string[];
548→  mapping: Record<string, string>;
549→  timeline: ComponentTimelineSnapshot[];
550→  error?: string;
551→}> {
552→  log(conversationId, "Starting componentisation process");
553→
554→  const config = getComponentisationConfig();
555→
556→  if (!config) {
557→    log(conversationId, "No config, skipping componentisation");
558→    return {
559→      components: [],
560→      mapping: {},
561→      timeline: [],
562→      error: "Componentisation: No API key configured",
563→    };
564→  }
565→
566→  // Step 1: Identify components (or use custom components if provided)
567→  let components: string[];
568→  if (customComponents && customComponents.length > 0) {
569→    // Normalize custom components - strip leading "- " prefix
570→    components = customComponents.map((c) => c.replace(/^-\s*/, ""));
571→    log(
572→      conversationId,
573→      `Using ${components.length} custom components (normalized)`,
574→    );
575→  } else {
576→    onProgress?.("identifying");
577→    components = await identifyComponents(
578→      conversation,
579→      config,
580→      customPrompt,
581→      conversationId,
582→    );
583→
584→    if (components.length === 0) {
585→      log(conversationId, "No components identified");
586→      return {
587→        components: [],
588→        mapping: {},
589→        timeline: [],
590→        error: "Componentisation: Failed to identify components (API error)",
591→      };
592→    }
593→  }
594→
595→  // Step 2: Map components to IDs
596→  onProgress?.("mapping");
597→  const componentDescriptions = customPrompt || getDefaultComponentIdentificationPrompt();
598→  const mapping = await mapComponentsToIds(
599→    conversation,
600→    components,
601→    config,
602→    componentDescriptions,
603→    conversationId,
604→  );
605→
606→  // Check if there are unmapped parts and add "other" component if needed
607→  const totalParts = conversation.messages.reduce(
608→    (sum, msg) => sum + msg.parts.length,
609→    0,
610→  );
611→  const mappedParts = Object.keys(mapping).length;
612→  const finalComponents =
613→    mappedParts < totalParts && !components.includes("other")
614→      ? [...components, "other"]
615→      : components;
616→
617→  // Step 3: Build timeline
618→  const timeline = buildComponentTimeline(
619→    conversation,
620→    mapping,
621→    conversationId,
622→  );
623→
624→  log(conversationId, "Completed componentisation");
625→  return { components: finalComponents, mapping, timeline };
626→}
